script:
// Independent implementation of the public Zazhimi magazine API; no app login.
var API='https://android2026.zazhimi.net/api',UA='ZaZhiMi_6.0.0';
function fail(s){throw new Error('杂志迷：'+s);}
async function api(path){var r=await triomi.fetch(API+path,{headers:{'User-Agent':UA}});if(r.status!==200)fail('HTTP '+r.status);var j;try{j=JSON.parse(r.body);}catch(e){fail('接口未返回公开 JSON 数据');}if(String(j.status)!=='200')fail(j.error||'接口拒绝请求');return j;}
function idFor(url,snapshot){var id=snapshot&&snapshot.remoteId;if(!/^\d+$/.test(String(id||'')))id=(url.match(/[?&]a=(\d+)/)||[])[1];if(!/^\d+$/.test(String(id||''))||Number(id)<1)fail('刊物编号无效');return String(id);}
function image(s){if(typeof s!=='string')fail('图片地址缺失');s=s.replace(/^http:\/\//,'https://');if(!/^https:\/\/(?:img2020|api)\.zazhimi\.net\//.test(s)||/[\s\\]/.test(s))fail('图片地址无效');return s;}
function item(x){if(!/^\d+$/.test(String(x.magId||''))||!x.magName)fail('刊物元数据不完整');var cover=x.magCover;if(!cover&&x.magDate){if(!/^[A-Za-z0-9_\/-]+\/$/.test(x.magDate)||x.magDate.indexOf('..')>=0)fail('封面目录无效');cover='https://img2020.zazhimi.net/aazzmpic-l/'+x.magDate+'001.jpg';}return {remoteId:String(x.magId),title:x.magName,url:API+'/show.php?a='+x.magId,coverUrl:cover?image(cover):undefined,author:String(x.magName).split(' ')[0],status:'completed',tags:['杂志']};}
function list(rows){if(!Array.isArray(rows))fail('刊物列表格式无效');return rows.filter(function(x){return !/^ad\//i.test(x.magDate||'');}).map(item);}
async function discover(url,page){return list((await api('/index.php?p='+page+'&s=20')).new);}
async function search(q,page){return list((await api('/search.php?k='+encodeURIComponent(q)+'&p='+page+'&s=20')).magazine);}
async function show(id){var j=await api('/show.php?a='+id);if(!Array.isArray(j.content)||!j.content.length)fail('刊物全文为空或已下架');j.content.forEach(function(x){if(String(x.magId)!==id||!x.magName)fail('刊物全文编号不一致');image(x.magPic);});return j.content;}
async function detail(url,snapshot){var id=idFor(url,snapshot),rows=await show(id),x=rows[0];return {item:{remoteId:id,title:x.magName,url:API+'/show.php?a='+id,coverUrl:image(x.magPic),author:x.magName.split(' ')[0],status:'completed',tags:['杂志']},chapters:[{remoteId:id,title:'全本',url:API+'/show.php?a='+id,number:1,volumeTitle:'整刊',locked:false}]};}
async function content(url,chapter){var rows=await show(idFor(url,chapter));return {images:rows.map(function(x){return image(x.magPic);}),headers:{'User-Agent':UA}};}
